-- Yummy menu replacement/update
-- Generated from the exported schema supplied by the user.
-- Prices are stored in poisha: 45000 = BDT 450.00.
-- This script updates/replaces only demo menu categories/products/translations.
-- It does NOT delete users, orders, settings, uploads, media, reservations or payments.

START TRANSACTION;

-- Remove old demo products that are no longer part of the new menu.
DELETE ct FROM `content_translations` ct INNER JOIN `products` p ON ct.`entity`='products' AND ct.`entity_id`=p.`id` WHERE p.`slug` IN ('shorshe-ilish','kacchi-for-two','family-kacchi','sharing-kala-bhuna','ilish-for-two','family-ilish');
DELETE FROM `products` WHERE `slug` IN ('shorshe-ilish','kacchi-for-two','family-kacchi','sharing-kala-bhuna','ilish-for-two','family-ilish');

-- Create/update menu categories and remember their IDs.
SET @cat_biryani=LAST_INSERT_ID();
SET @cat_street_food=LAST_INSERT_ID();
SET @cat_pizza=LAST_INSERT_ID();
SET @cat_shawarma=LAST_INSERT_ID();
SET @cat_burger_fries=LAST_INSERT_ID();
SET @cat_chicken=LAST_INSERT_ID();
SET @cat_beef=LAST_INSERT_ID();
SET @cat_paratha_sides=LAST_INSERT_ID();
SET @cat_others=LAST_INSERT_ID();

-- English translations for categories (Bangla remains the base content).

-- Create/update products. Existing matching slugs are updated instead of duplicated.
SET @prod_kacchi_biryani=LAST_INSERT_ID();

SET @prod_beef_tehari=LAST_INSERT_ID();

SET @prod_fuchka=LAST_INSERT_ID();

SET @prod_chotpoti=LAST_INSERT_ID();

SET @prod_jhal_muri=LAST_INSERT_ID();

SET @prod_chicken_pizza=LAST_INSERT_ID();

SET @prod_beef_pizza=LAST_INSERT_ID();

SET @prod_chicken_shawarma=LAST_INSERT_ID();

SET @prod_beef_shawarma=LAST_INSERT_ID();

SET @prod_chicken_burger=LAST_INSERT_ID();

SET @prod_beef_burger=LAST_INSERT_ID();

SET @prod_french_fries=LAST_INSERT_ID();

SET @prod_fried_chicken=LAST_INSERT_ID();

SET @prod_chicken_grill=LAST_INSERT_ID();

SET @prod_chicken_curry=LAST_INSERT_ID();

SET @prod_kala_bhuna=LAST_INSERT_ID();

SET @prod_beef_curry=LAST_INSERT_ID();

SET @prod_beef_kebab=LAST_INSERT_ID();

SET @prod_plain_paratha=LAST_INSERT_ID();

SET @prod_egg_paratha=LAST_INSERT_ID();

SET @prod_mughlai_paratha=LAST_INSERT_ID();

SET @prod_chicken_noodles=LAST_INSERT_ID();

SET @prod_chicken_pasta=LAST_INSERT_ID();

SET @prod_borhani=LAST_INSERT_ID();

SET @prod_sweet_lassi=LAST_INSERT_ID();

-- Remove old empty demo categories after products have been moved/deleted.
DELETE c FROM `categories` c LEFT JOIN `products` p ON p.`category_id`=c.`id` WHERE c.`slug` IN ('meat','fish') AND p.`id` IS NULL;

COMMIT;

-- Verification query
SELECT p.`id`, c.`name` AS `category`, p.`name`, p.`slug`, ROUND(p.`price`/100,2) AS `price_bdt`, p.`available`, p.`featured` FROM `products` p INNER JOIN `categories` c ON c.`id`=p.`category_id` ORDER BY c.`sort_order`, p.`sort_order`, p.`id`;